sketch:
// Digital sensors — four modules, four ways of reading them.
//
// Tilt and motion are on/off. Flame and sound give both an analogue reading
// and a comparator output that crosses at half scale. Flip Tilted or Motion,
// or move the Flame/Noise slider, and run it.

void setup() {
  Serial.begin(9600);
  pinMode(2, INPUT);
  pinMode(3, INPUT);
  pinMode(4, INPUT);
  pinMode(5, INPUT);
}

void loop() {
  Serial.print("tilt ");
  Serial.print(digitalRead(2));
  Serial.print("  motion ");
  Serial.print(digitalRead(3));
  Serial.print("  flame ");
  Serial.print(analogRead(A0));
  Serial.print("/");
  Serial.print(digitalRead(4));
  Serial.print("  sound ");
  Serial.print(analogRead(A1));
  Serial.print("/");
  Serial.println(digitalRead(5));
  delay(250);
}
